import {
  RunAgentInput,
  AbstractAgent,
  AgentConfig,
  BaseEvent,
  EventType,
  RunStartedEvent,
  RunFinishedEvent,
  RunErrorEvent,
  TextMessageStartEvent,
  TextMessageContentEvent,
  TextMessageEndEvent,
  ThinkingStartEvent,
  ThinkingTextMessageStartEvent,
  ThinkingTextMessageContentEvent,
  ThinkingTextMessageEndEvent,
  ThinkingEndEvent,
} from "@ag-ui/client";
import { Observable, Subscriber } from "rxjs";
import { N8nConfig, N8nRequestBody, StreamContext } from "./types";
import { generateRunId, generateThreadId } from "./utils";
import { startActiveObservation, ObservationChain, ObservationAgent, type SpanContext } from "@cloudbase/agent-observability";
import { Logger, noopLogger } from "@cloudbase/agent-shared";

export class N8nAgentError extends Error {
  code?: string;
  constructor(message: string, code?: string) {
    super(message);
    this.name = "N8nAgentError";
    if (code) this.code = code;
  }
}

/**
 * n8n Agent Adapter
 *
 * Connects to n8n workflows via Streaming Webhook.
 * Supports basic text streaming (TEXT_MESSAGE_* events only).
 * Tool calls are handled internally within the n8n workflow.
 *
 * Environment Variables:
 * - N8N_WEBHOOK_URL: n8n webhook URL (required if not provided in config)
 *
 * @example
 * ```typescript
 * // Using environment variables
 * // N8N_WEBHOOK_URL=https://n8n.example.com/webhook/chat
 * const agent = new N8nAgent();
 *
 * // Or explicit configuration with Basic Auth
 * const agent = new N8nAgent({
 *   n8nConfig: {
 *     webhookUrl: "https://n8n.example.com/webhook/chat",
 *     request: {
 *       headers: { Authorization: `Basic ${Buffer.from("user:pass").toString("base64")}` }
 *     }
 *   }
 * });
 *
 * agent.run({
 *   threadId: "thread-xxx",
 *   runId: "run-xxx",
 *   messages: [{ role: "user", content: "Hello" }]
 * }).subscribe(event => {
 *   console.log(event);
 * });
 * ```
 */
export class N8nAgent extends AbstractAgent {
  protected n8nConfig: Required<Pick<N8nConfig, "webhookUrl">> &
    N8nConfig;
  private logger: Logger;

  constructor(config?: AgentConfig & { n8nConfig?: N8nConfig; logger?: Logger }) {
    super(config || {});

    // Resolve webhook URL from config or environment variable
    const webhookUrl =
      config?.n8nConfig?.webhookUrl ||
      (typeof process !== "undefined" && process.env?.N8N_WEBHOOK_URL);

    if (!webhookUrl) {
      throw new N8nAgentError(
        "webhookUrl is required. Provide it in n8nConfig or set N8N_WEBHOOK_URL environment variable.",
        "MISSING_WEBHOOK_URL"
      );
    }

    // Validate webhook URL scheme
    try {
      const parsed = new URL(webhookUrl);
      if (!["http:", "https:"].includes(parsed.protocol)) {
        throw new Error("Invalid protocol");
      }
    } catch {
      throw new N8nAgentError(
        "webhookUrl must be a valid http or https URL.",
        "INVALID_WEBHOOK_URL"
      );
    }

    this.n8nConfig = {
      webhookUrl,
      request: config?.n8nConfig?.request,
    };

    // Setup logger
    const baseLogger = config?.logger ?? noopLogger;
    this.logger = baseLogger.child?.({ component: "n8n-agent" }) ?? baseLogger;
  }

  /**
   * Extract parent SpanContext from AG-UI server's forwardedProps.
   * Returns undefined if not available (observability will create a new root trace).
   */
  private _extractParentSpanContext(input: RunAgentInput): SpanContext | undefined {
    try {
      const serverContext = input.forwardedProps?.__agui_server_context;
      if (serverContext?.traceId && serverContext?.spanId) {
        return {
          traceId: serverContext.traceId,
          spanId: serverContext.spanId,
          traceFlags: serverContext.traceFlags ?? 1,
          isRemote: true,
        };
      }
    } catch {
      // Silent fail - don't block business logic
    }
    return undefined;
  }

  /**
   * Run the agent with n8n webhook streaming
   */
  run(input: RunAgentInput): Observable<BaseEvent> {
    return new Observable<BaseEvent>((subscriber) => {
      // Create run-specific logger
      const logger = this.logger.child?.({ runId: input.runId, threadId: input.threadId }) ?? this.logger;

      // Extract parent span context from AG-UI.Server for trace linkage
      const parentSpanContext = this._extractParentSpanContext(input);

      // Start observability with Adapter.n8n [CHAIN]
      startActiveObservation(
        "Adapter.n8n",
        async (adapterSpan: ObservationChain) => {
          adapterSpan.update({
            input: {
              webhookUrl: this.n8nConfig.webhookUrl,
              messageCount: input.messages.length,
            },
          });

        try {
          await this._runWithObservability(subscriber, input, adapterSpan, logger);
          adapterSpan.update({
            output: { status: "completed" },
          });
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : "Unknown error";
          adapterSpan.setErrorStatus(errorMessage);
          adapterSpan.update({
            level: "ERROR",
            statusMessage: errorMessage,
          });
          throw error;
        }
        },
        { asType: "chain", parentSpanContext }
      ).catch(async (error) => {
        // Observability failure should not block business flow - fallback to run without observability
        logger.error?.("Adapter span error, falling back to non-observability run:", error);
        try {
          const threadId = input.threadId || generateThreadId();
          const runId = input.runId || generateRunId();
          const messageId = `${threadId}:${runId}`;
          const context: StreamContext = {
            threadId,
            runId,
            messageId,
          };
          await this._run(subscriber, input, context, logger);
        } catch (fallbackError) {
          logger.error?.("Fallback run also failed:", fallbackError);
          subscriber.next({
            type: EventType.RUN_ERROR,
            message: `n8n adapter error: ${fallbackError instanceof Error ? fallbackError.message : "Unknown error"}`,
            code: "RUN_ERROR",
          } as RunErrorEvent);
        }
        subscriber.complete();
      });
    });
  }

  private async _runWithObservability(
    subscriber: Subscriber<BaseEvent>,
    input: RunAgentInput,
    adapterSpan: ObservationChain,
    logger: Logger
  ): Promise<void> {
    const threadId = input.threadId || generateThreadId();
    const runId = input.runId || generateRunId();
    const messageId = `${threadId}:${runId}`;

    const context: StreamContext = {
      threadId,
      runId,
      messageId,
    };

    // Start n8n Webhook [AGENT] span as child of Adapter.n8n
    await startActiveObservation(
      "n8n Webhook",
      async (workflowSpan: ObservationAgent) => {
        workflowSpan.update({
          input: {
            webhookUrl: this.n8nConfig.webhookUrl,
            threadId,
            runId,
          },
        });

        try {
          await this._run(subscriber, input, context, logger);
          workflowSpan.update({
            output: { status: "completed" },
          });
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : "Unknown error";
          workflowSpan.setErrorStatus(errorMessage);
          workflowSpan.update({
            level: "ERROR",
            statusMessage: errorMessage,
          });
          throw error;
        }
      },
      { asType: "agent" }
    );
  }

  private async _run(
    subscriber: Subscriber<BaseEvent>,
    input: RunAgentInput,
    context: StreamContext,
    logger: Logger
  ): Promise<void> {
    const { threadId, runId, messageId } = context;

    try {
      logger.info?.("Run started");

      // Emit RUN_STARTED event
      subscriber.next({
        type: EventType.RUN_STARTED,
        threadId,
        runId,
      } as RunStartedEvent);

      // Prepare request body for n8n Chat Trigger
      // n8n expects: { chatInput: string, sessionId: string }
      // Extract the last user message as chatInput
      const lastUserMessage = input.messages
        .filter((msg) => msg.role === "user")
        .pop();

      if (!lastUserMessage) {
        throw new N8nAgentError(
          "No user message found in messages array",
          "MISSING_USER_MESSAGE"
        );
      }

      const chatInput = typeof lastUserMessage.content === "string"
        ? lastUserMessage.content
        : JSON.stringify(lastUserMessage.content);

      const requestBody: N8nRequestBody = {
        chatInput,
        sessionId: threadId,
      };

      // Build request headers
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
        Accept: "text/plain, application/json",
        ...(this.n8nConfig.request?.headers || {}),
      };

      const url = this.n8nConfig.webhookUrl;

      // Make the fetch request with timeout
      const controller = new AbortController();
      const timeout = this.n8nConfig.request?.timeout || 120000;
      const timeoutId = setTimeout(() => controller.abort(), timeout);

      const response = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(requestBody),
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new N8nAgentError(
          `HTTP error! status: ${response.status}, statusText: ${response.statusText}`,
          `HTTP_${response.status}`
        );
      }

      if (!response.body) {
        throw new N8nAgentError(
          "Response body is null",
          "NULL_RESPONSE_BODY"
        );
      }

      // Process the stream
      await this.processTextStream(response.body, subscriber, context, messageId);

      // Emit RUN_FINISHED event
      subscriber.next({
        type: EventType.RUN_FINISHED,
        threadId,
        runId,
      } as RunFinishedEvent);

      logger.info?.("Run completed");
    } catch (error: unknown) {
      logger.error?.("[n8nAgent] Error:", error);

      let code = "UNKNOWN_ERROR";
      let message = "An unknown error occurred";

      if (error instanceof N8nAgentError) {
        code = error.code || "N8N_AGENT_ERROR";
        message = error.message;
      } else if (error instanceof Error) {
        if (error.name === "AbortError") {
          code = "TIMEOUT";
          message = `Request timeout after ${this.n8nConfig.request?.timeout || 120000}ms`;
        } else {
          code = error.name || "ERROR";
          message = error.message;
        }
      }

      subscriber.next({
        type: EventType.RUN_ERROR,
        code,
        message: `n8n agent error: ${message}`,
      } as RunErrorEvent);

      logger.error?.("Run failed:", { code, message });
      throw error;
    } finally {
      subscriber.complete();
    }
  }

  /**
   * Process the HTTP stream and emit AGUI events
   * Parses n8n JSON Lines format and maps "item" type content to TEXT_MESSAGE_* events
   * Also handles <think>...</think> tags to emit THINKING_* events
   *
   * N8n returns JSON Lines format:
   * - {"type": "begin", "metadata": {...}}
   * - {"type": "item", "content": "...", "metadata": {...}}
   * - {"type": "end", "metadata": {...}}
   *
   * Think content is wrapped in <think>...</think> tags and may span multiple items.
   * Example:
   *   item1: "<think>\n用户要求"
   *   item2: "思考内容</think>\n\n正式回答"
   */
  private async processTextStream(
    body: ReadableStream<Uint8Array>,
    subscriber: Subscriber<BaseEvent>,
    context: StreamContext,
    messageId: string
  ): Promise<void> {
    const reader = body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    // State for tracking think content parsing
    const parseState = {
      // Text message state
      textStarted: false,
      // Thinking state
      thinkingStarted: false,
      thinkingMessageStarted: false,
      // Content buffer for handling split tags
      contentBuffer: "",
    };

    try {
      while (true) {
        const { done, value } = await reader.read();

        if (done) {
          break;
        }

        // Decode the chunk
        const chunk = decoder.decode(value, { stream: true });
        buffer += chunk;

        // Process complete lines (JSON Lines format)
        const lines = buffer.split("\n");
        buffer = lines.pop() || ""; // Keep incomplete line in buffer

        for (const line of lines) {
          const trimmedLine = line.trim();
          if (!trimmedLine) continue;

          try {
            // Parse JSON line
            const event = JSON.parse(trimmedLine);
            const eventType = event.type;

            // Only process "item" type events with content
            if (eventType === "item") {
              const content = event.content || "";
              this.processContentChunk(content, subscriber, messageId, parseState);
            }
            // Ignore "begin" and "end" types (metadata only)
          } catch (e) {
            // Skip non-JSON lines (malformed data)
            continue;
          }
        }
      }

      // Process any remaining content in buffer
      if (buffer.trim()) {
        try {
          const event = JSON.parse(buffer.trim());
          if (event.type === "item" && event.content) {
            this.processContentChunk(event.content, subscriber, messageId, parseState);
          }
        } catch (e) {
          // Ignore parse errors for final buffer
        }
      }

      // Close any open states
      this.closeParseState(subscriber, messageId, parseState);
    } catch (error) {
      this.logger.error?.("[n8nAgent] Stream processing error:", error);
      throw error;
    } finally {
      reader.releaseLock();
    }
  }

  /**
   * Process a content chunk and emit appropriate events based on <think> tags
   */
  private processContentChunk(
    content: string,
    subscriber: Subscriber<BaseEvent>,
    messageId: string,
    state: {
      textStarted: boolean;
      thinkingStarted: boolean;
      thinkingMessageStarted: boolean;
      contentBuffer: string;
    }
  ): void {
    // Append content to buffer for processing
    state.contentBuffer += content;

    // Process buffer until no more complete patterns can be extracted
    while (state.contentBuffer.length > 0) {
      // Case 1: Currently in thinking mode
      if (state.thinkingStarted) {
        const thinkEndIndex = state.contentBuffer.indexOf("</think>");

        if (thinkEndIndex !== -1) {
          // Found </think> - extract think content and close thinking
          const thinkContent = state.contentBuffer.substring(0, thinkEndIndex);

          if (thinkContent.length > 0 && state.thinkingMessageStarted) {
            subscriber.next({
              type: EventType.THINKING_TEXT_MESSAGE_CONTENT,
              delta: thinkContent,
            } as ThinkingTextMessageContentEvent);
          }

          // Close thinking message and thinking state
          if (state.thinkingMessageStarted) {
            subscriber.next({
              type: EventType.THINKING_TEXT_MESSAGE_END,
            } as ThinkingTextMessageEndEvent);
            state.thinkingMessageStarted = false;
          }

          subscriber.next({
            type: EventType.THINKING_END,
          } as ThinkingEndEvent);
          state.thinkingStarted = false;

          // Close current text message before starting new one
          if (state.textStarted) {
            subscriber.next({
              type: EventType.TEXT_MESSAGE_END,
              messageId,
            } as TextMessageEndEvent);
            state.textStarted = false;
          }

          // Remove processed content including </think> tag
          state.contentBuffer = state.contentBuffer.substring(thinkEndIndex + 8); // 8 = "</think>".length

          // Skip leading whitespace/newlines after </think> - they are just formatting, not content
          state.contentBuffer = state.contentBuffer.replace(/^[\s\n]+/, "");
        } else {
          // No </think> found - emit all as thinking content
          if (!state.thinkingMessageStarted) {
            subscriber.next({
              type: EventType.THINKING_TEXT_MESSAGE_START,
            } as ThinkingTextMessageStartEvent);
            state.thinkingMessageStarted = true;
          }

          subscriber.next({
            type: EventType.THINKING_TEXT_MESSAGE_CONTENT,
            delta: state.contentBuffer,
          } as ThinkingTextMessageContentEvent);

          state.contentBuffer = "";
          return; // Wait for more data
        }
      }
      // Case 2: Not in thinking mode - look for <think> start
      else {
        const thinkStartIndex = state.contentBuffer.indexOf("<think>");

        if (thinkStartIndex !== -1) {
          // Found <think> - emit any text before it as regular content
          const textBeforeThink = state.contentBuffer.substring(0, thinkStartIndex);

          if (textBeforeThink.length > 0) {
            // Check if textBeforeThink is only whitespace
            if (/^\s*$/.test(textBeforeThink)) {
              // Whitespace before think is just formatting,
              // but we need to close any open text message
              if (state.textStarted) {
                subscriber.next({
                  type: EventType.TEXT_MESSAGE_END,
                  messageId,
                } as TextMessageEndEvent);
                state.textStarted = false;
              }
            } else {
              // Non-whitespace content before think
              if (!state.textStarted) {
                subscriber.next({
                  type: EventType.TEXT_MESSAGE_START,
                  messageId,
                  role: "assistant",
                } as TextMessageStartEvent);
                state.textStarted = true;
              }

              subscriber.next({
                type: EventType.TEXT_MESSAGE_CONTENT,
                messageId,
                delta: textBeforeThink,
              } as TextMessageContentEvent);
            }
          }

          // End any open text message before starting thinking
          if (state.textStarted) {
            subscriber.next({
              type: EventType.TEXT_MESSAGE_END,
              messageId,
            } as TextMessageEndEvent);
            state.textStarted = false;
          }

          // Start thinking mode
          subscriber.next({
            type: EventType.THINKING_START,
          } as ThinkingStartEvent);
          state.thinkingStarted = true;

          // Remove processed content including <think> tag
          state.contentBuffer = state.contentBuffer.substring(thinkStartIndex + 7); // 7 = "<think>".length

          // Start thinking message if there's content immediately after <think>
          if (state.contentBuffer.length > 0 && !state.thinkingMessageStarted) {
            subscriber.next({
              type: EventType.THINKING_TEXT_MESSAGE_START,
            } as ThinkingTextMessageStartEvent);
            state.thinkingMessageStarted = true;
          }
        } else {
          // No <think> found - emit all as regular text content
          if (state.contentBuffer.length > 0) {
            if (!state.textStarted) {
              subscriber.next({
                type: EventType.TEXT_MESSAGE_START,
                messageId,
                role: "assistant",
              } as TextMessageStartEvent);
              state.textStarted = true;
            }

            subscriber.next({
              type: EventType.TEXT_MESSAGE_CONTENT,
              messageId,
              delta: state.contentBuffer,
            } as TextMessageContentEvent);

            state.contentBuffer = "";
          }
          return; // Wait for more data
        }
      }
    }
  }

  /**
   * Close any open parse states at the end of stream
   */
  private closeParseState(
    subscriber: Subscriber<BaseEvent>,
    messageId: string,
    state: {
      textStarted: boolean;
      thinkingStarted: boolean;
      thinkingMessageStarted: boolean;
      contentBuffer: string;
    }
  ): void {
    // Handle any remaining content in buffer
    if (state.contentBuffer.length > 0) {
      if (state.thinkingStarted) {
        // Unclosed think tag - emit remaining as thinking content
        if (!state.thinkingMessageStarted) {
          subscriber.next({
            type: EventType.THINKING_TEXT_MESSAGE_START,
          } as ThinkingTextMessageStartEvent);
          state.thinkingMessageStarted = true;
        }

        subscriber.next({
          type: EventType.THINKING_TEXT_MESSAGE_CONTENT,
          delta: state.contentBuffer,
        } as ThinkingTextMessageContentEvent);
      } else {
        // Regular text content
        if (!state.textStarted) {
          subscriber.next({
            type: EventType.TEXT_MESSAGE_START,
            messageId,
            role: "assistant",
          } as TextMessageStartEvent);
          state.textStarted = true;
        }

        subscriber.next({
          type: EventType.TEXT_MESSAGE_CONTENT,
          messageId,
          delta: state.contentBuffer,
        } as TextMessageContentEvent);
      }
      state.contentBuffer = "";
    }

    // Close thinking state if still open
    if (state.thinkingStarted) {
      if (state.thinkingMessageStarted) {
        subscriber.next({
          type: EventType.THINKING_TEXT_MESSAGE_END,
        } as ThinkingTextMessageEndEvent);
      }

      subscriber.next({
        type: EventType.THINKING_END,
      } as ThinkingEndEvent);

      state.thinkingStarted = false;
      state.thinkingMessageStarted = false;
    }

    // Close text message if started
    if (state.textStarted) {
      subscriber.next({
        type: EventType.TEXT_MESSAGE_END,
        messageId,
      } as TextMessageEndEvent);
    } else {
      // Handle completely empty response
      subscriber.next({
        type: EventType.TEXT_MESSAGE_START,
        messageId,
        role: "assistant",
      } as TextMessageStartEvent);
      subscriber.next({
        type: EventType.TEXT_MESSAGE_CONTENT,
        messageId,
        delta: "No response from N8n workflow.",
      } as TextMessageContentEvent);
      subscriber.next({
        type: EventType.TEXT_MESSAGE_END,
        messageId,
      } as TextMessageEndEvent);
    }
  }
}
